CREATE TABLE bedrock_kb (
  id uuid PRIMARY KEY,
  embedding vector(1024),
  chunks text,
  metadata jsonb
);
CREATE INDEX ON bedrock_kb USING hnsw (embedding vector_cosine_ops);
```

